#include <Aevrynd/HeightField3D.h>
#include <chrono>
#include <cmath>
#include <iostream>

using namespace Aevrynd;
bool Near(float left,float right,float tolerance=.01f){return std::abs(left-right)<=tolerance;}
int main(){
    HeightField3D field({{0,0,0},3,3,1});for(unsigned z=0;z<3;++z)for(unsigned x=0;x<3;++x)field.SetHeight(x,z,float(x+z));if(!Near(field.SampleHeight(.5f,.5f),1.f)||field.Contains(-1,0)||!field.Contains(2,2)){std::cerr<<"Height interpolation or bounds failed\n";return 1;}const Vec3 normal=field.SampleNormal(1,1);if(normal.y<.55f||normal.x>-.2f||normal.z>-.2f){std::cerr<<"Height normal failed\n";return 2;}const Mesh3D mesh=field.CreateMesh();if(!mesh.Valid()||mesh.vertices.size()!=9||mesh.indices.size()!=24||UnpackNormalSnorm8(mesh.vertices[4].normal).y<.5f){std::cerr<<"Height mesh generation failed\n";return 3;}
    HeightField3D first({{-32,0,-32},65,65,1}),second({{-32,0,-32},65,65,1}),different({{-32,0,-32},65,65,1});first.Generate(42,8,.03f,4);second.Generate(42,8,.03f,4);different.Generate(43,8,.03f,4);if(!Near(first.Height(17,29),second.Height(17,29),.00001f)||Near(first.Height(17,29),different.Height(17,29),.00001f)||first.MaximumHeight()-first.MinimumHeight()<2.f){std::cerr<<"Deterministic generation failed\n";return 4;}first.FlattenCircle({0,0,0},4,1.5f,4);if(!Near(first.SampleHeight(0,0),1.5f)||Near(first.SampleHeight(20,20),1.5f)){std::cerr<<"Terrain flattening failed\n";return 5;}
    HeightField3D ultraA({{-128,0,-128},257,257,1}),ultraB({{-128,0,-128},257,257,1}),ultraDifferent({{-128,0,-128},257,257,1});HeightFieldUltraSettings3D ultraSettings;const auto ultraStart=std::chrono::steady_clock::now();if(!ultraA.GenerateUltra(90210,ultraSettings)){std::cerr<<"Ultra generation failed\n";return 7;}const auto ultraElapsed=std::chrono::steady_clock::now()-ultraStart;if(!ultraB.GenerateUltra(90210,ultraSettings)||!ultraDifferent.GenerateUltra(90211,ultraSettings)){std::cerr<<"Ultra repeat generation failed\n";return 8;}bool seedDifference=false;for(unsigned z=0;z<257;++z)for(unsigned x=0;x<257;++x){const float a=ultraA.Height(x,z),b=ultraB.Height(x,z),c=ultraDifferent.Height(x,z);if(!std::isfinite(a)||a!=b){std::cerr<<"Ultra finite or deterministic height failed\n";return 9;}seedDifference|=std::abs(a-c)>.001f;}if(!seedDifference||ultraA.MaximumHeight()-ultraA.MinimumHeight()<8.f){std::cerr<<"Ultra seed or relief failed\n";return 10;}for(Vec3 point:{Vec3{-128,0,-128},Vec3{0,0,0},Vec3{128,0,128},Vec3{-120,0,95}}){const Vec3 surfaceNormal=ultraA.SampleNormal(point.x,point.z);const float length=Length(surfaceNormal);if(!std::isfinite(length)||length<.99f||length>1.01f||surfaceNormal.y<=0){std::cerr<<"Ultra normal failed\n";return 11;}}
    const float sentinel=ultraA.Height(33,77);HeightFieldUltraSettings3D limited=ultraSettings;limited.maximumSamples=100;if(ultraA.GenerateUltra(1,limited)||ultraA.Height(33,77)!=sentinel){std::cerr<<"Ultra capacity atomicity failed\n";return 12;}limited=ultraSettings;limited.maximumScratchBytes=1024;if(ultraA.GenerateUltra(1,limited)||ultraA.Height(33,77)!=sentinel){std::cerr<<"Ultra scratch atomicity failed\n";return 13;}if(ultraElapsed>std::chrono::seconds(2)){std::cerr<<"Ultra generation performance failed\n";return 14;}
    limited=ultraSettings;limited.maximumAbsoluteCoordinate=100.f;if(ultraA.GenerateUltra(1,limited)||ultraA.Height(33,77)!=sentinel){std::cerr<<"Ultra coordinate bound failed\n";return 15;}
    constexpr int Samples=100000;float total{};const auto start=std::chrono::steady_clock::now();for(int index=0;index<Samples;++index)total+=first.SampleHeight(float(index%63)-31.5f,float((index*7)%63)-31.5f);const uint64_t averageNs=uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count())/Samples;if(averageNs>500||!std::isfinite(total)){std::cerr<<"Height sampling throughput failed\n";return 6;}std::cout<<"samples="<<first.SampleCount()<<" range="<<first.MaximumHeight()-first.MinimumHeight()<<" vertices="<<mesh.vertices.size()<<" averageNs="<<averageNs<<" ultraRange="<<ultraA.MaximumHeight()-ultraA.MinimumHeight()<<" ultraMilliseconds="<<std::chrono::duration_cast<std::chrono::milliseconds>(ultraElapsed).count()<<'\n';return 0;
}
